window.HOEREN_TESTS[82] = {"id":"beim-hautarzt","name":"Beim Hautarzt","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist die Hautarztpraxis Dr. Sommer. Ihr Termin für die Hautkrebs-Vorsorge ist nächste Woche. Am Montag geht es leider nicht, und auch am Mittwoch haben wir keinen Platz. Wir haben Sie auf Dienstag um 9 Uhr gesetzt. Bitte kommen Sie ungeschminkt und ohne Creme auf der Haut. Bringen Sie Ihre Versichertenkarte mit. Auf Wiederhören!","gender":"f","q":"Wann ist der Termin?","opts":["Am Montag.","Am Dienstag.","Am Mittwoch."],"correct":1},{"transcript":"Hallo Tom, hier ist Markus. Also, ich habe seit Wochen einen roten Ausschlag am Arm, der juckt furchtbar. Cremes aus der Apotheke helfen nicht. Ich glaube, ich muss zum Hautarzt. Aber die haben so lange Wartezeiten! Kennst du eine Praxis mit schnellen Terminen? Ruf zurück, das macht mich verrückt!","gender":"m","q":"Was ist Markus' Problem?","opts":["Kopfschmerzen.","Husten.","Ein roter Ausschlag, der juckt."],"correct":2},{"transcript":"Achtung Patienten: Die Sonne wird stärker. Bitte schützen Sie Ihre Haut. Benutzen Sie eine Creme mit hohem Schutz, auch im Frühling. Gehen Sie zur Mittagszeit nicht zu lange in die Sonne. Und lassen Sie Ihre Muttermale einmal im Jahr kontrollieren. Vorsorge ist der beste Schutz!","gender":"m","q":"Was empfiehlt die Praxis?","opts":["Viel in die Sonne gehen.","Die Haut schützen.","Keine Creme benutzen."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Ich war beim Hautarzt wegen meiner Pickel. Er hat mir eine Creme verschrieben und gesagt, ich soll mehr Wasser trinken und weniger Süßes essen. Schon nach zwei Wochen ist die Haut besser! Ich bin so froh. Du hast doch auch Probleme, geh mal hin!","gender":"f","q":"Was hat der Hautarzt empfohlen?","opts":["Mehr schlafen.","Mehr Sport.","Mehr Wasser und weniger Süßes."],"correct":2},{"transcript":"Liebe Patienten: Unsere Praxis bietet ab Mai eine Akne-Sprechstunde speziell für Jugendliche an, jeden Mittwochnachmittag. Die Sprechstunde ist nicht für ältere Menschen und auch nicht für Babys. Auch eine Beratung zum richtigen Sonnenschutz gibt es. Bitte vereinbaren Sie vorher einen Termin. Die Wartezeit beträgt zurzeit etwa drei Wochen. Wir bitten um Geduld!","gender":"f","q":"Für wen ist die Akne-Sprechstunde?","opts":["Für Jugendliche.","Für ältere Menschen.","Für Babys."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer hat welches Problem? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Im Wartezimmer ist es voll. Geht es dir seit gestern besser?"},{"speaker":"Lisa","gender":"f","text":"Es geht mir nicht besser. Der Arzt kommt gleich zu uns."},{"speaker":"Lukas","gender":"m","text":"Bei mir sind es die Pickel im Gesicht. Seit einer Woche werden es immer mehr."},{"speaker":"Lisa","gender":"f","text":"Das kenne ich. Hat jemand von euch Warzen an den Fingern?"},{"speaker":"Lukas","gender":"m","text":"Warzen hat hier keiner. Die Hände sind in Ordnung."},{"speaker":"Lisa","gender":"f","text":"Ich habe einen Ausschlag am Arm und der ist rot und warm."},{"speaker":"Lukas","gender":"m","text":"Zeig das dem Arzt gleich. Tom ist wegen eines Punktes am Rücken hier."},{"speaker":"Lisa","gender":"f","text":"Tom kommt zur Muttermal-Kontrolle. Der Punkt ist neu und etwas dunkel."},{"speaker":"Lukas","gender":"m","text":"Sieht jemand Nagelpilz an den Füßen?"},{"speaker":"Lisa","gender":"f","text":"Nagelpilz hat auch keiner."},{"speaker":"Lukas","gender":"m","text":"Sara sagt seit dem Winter, dass die Beine weh tun."},{"speaker":"Lisa","gender":"f","text":"Sara hat trockene Haut. Sie nimmt jeden Abend Creme und es hilft kaum."},{"speaker":"Lukas","gender":"m","text":"Im Sommer wird das oft besser. Tim war gestern lange ohne Hut in der Sonne."},{"speaker":"Lisa","gender":"f","text":"Tim hat einen Sonnenbrand auf den Schultern. Er saß zu lange draußen."},{"speaker":"Lukas","gender":"m","text":"Das soll der Arzt heute ansehen."},{"speaker":"Lisa","gender":"f","text":"Ich öffne die Tür zum Arzt."}],"options":[{"letter":"a","text":"Ausschlag / Allergie"},{"letter":"b","text":"Insektenstich"},{"letter":"c","text":"Warzen"},{"letter":"d","text":"Haarausfall"},{"letter":"e","text":"Nagelpilz"},{"letter":"f","text":"Trockene Haut"},{"letter":"g","text":"Pickel / Akne"},{"letter":"h","text":"Muttermal-Kontrolle"},{"letter":"i","text":"Sonnenbrand"}],"items":[{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"a"},{"person":"Tom","correct":"h"},{"person":"Sara","correct":"f"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Patientin","gender":"f","text":"Guten Tag, ich brauche einen Termin beim Hautarzt, möglichst bald."},{"speaker":"Sprechstundenhilfe","gender":"f","text":"Gerne, ist es wegen Pickeln oder wegen trockener Haut? Das können wir nächste Woche machen."},{"speaker":"Patientin","gender":"f","text":"Nein, nicht wegen Pickeln und auch nicht wegen trockener Haut. Ein Muttermal hat sich verändert."},{"speaker":"Sprechstundenhilfe","gender":"f","text":"Dann kommen Sie bitte morgen, das prüfen wir gleich. Das ist wichtiger als Pickel oder trockene Haut."},{"speaker":"Patientin","gender":"f","text":"Ja, morgen ist gut. Vielen Dank für den schnellen Termin."}],"q":"Warum bekommt sie schnell einen Termin?","opts":["Wegen Pickeln.","Ein Muttermal hat sich verändert.","Wegen trockener Haut."],"correct":1},{"lines":[{"speaker":"Arzt","gender":"m","text":"Guten Tag, wie lange haben Sie den Ausschlag schon?"},{"speaker":"Patient","gender":"m","text":"Seit zwei Wochen schon, und es wird nicht besser."},{"speaker":"Arzt","gender":"m","text":"Haben Sie etwas Neues gegessen? Zum Beispiel Nüsse oder Fisch?"},{"speaker":"Patient","gender":"m","text":"Nüsse esse ich nie, und Fisch mag ich nicht. Aber ja, viele Erdbeeren. Ich habe fast jeden Tag welche gegessen."},{"speaker":"Arzt","gender":"m","text":"Dann kommen die Beschwerden wahrscheinlich von den Erdbeeren, nicht von Nüssen oder Fisch."}],"q":"Was hat der Patient Neues gegessen?","opts":["Nüsse.","Erdbeeren.","Fisch."],"correct":1},{"lines":[{"speaker":"Patientin","gender":"f","text":"Guten Tag, welchen Sonnenschutz empfehlen Sie? Brauche ich überhaupt welchen?"},{"speaker":"Ärztin","gender":"f","text":"Ja, Sie brauchen Schutz. Faktor 10 ist zu wenig, und ohne Creme geht es nicht."},{"speaker":"Patientin","gender":"f","text":"Auch im Frühling? Manche sagen, dann reicht Faktor 10 oder sogar keiner?"},{"speaker":"Ärztin","gender":"f","text":"Ja, die Sonne ist auch dann stark. Nehmen Sie mindestens Faktor 30, nicht Faktor 10 und nicht ohne Creme."},{"speaker":"Patientin","gender":"f","text":"Gut, dann kaufe ich Faktor 30. Danke für den Tipp."}],"q":"Welchen Schutzfaktor empfiehlt die Ärztin?","opts":["Mindestens Faktor 30.","Faktor 10.","Keinen."],"correct":0},{"lines":[{"speaker":"Arzt","gender":"m","text":"Bitte tragen Sie die Creme zweimal am Tag auf, nicht nur einmal und nicht jede Stunde."},{"speaker":"Patient","gender":"m","text":"Morgens und abends? Oder wirklich jede Stunde? Einmal am Tag wäre einfacher."},{"speaker":"Arzt","gender":"m","text":"Genau, morgens und abends, also zweimal am Tag. Nicht jede Stunde, das ist zu oft, und einmal reicht nicht. Und nicht in die Sonne damit."},{"speaker":"Patient","gender":"m","text":"Verstanden, danke. Zweimal am Tag, morgens und abends."}],"q":"Wie oft soll der Patient die Creme auftragen?","opts":["Zweimal am Tag.","Einmal am Tag.","Jede Stunde."],"correct":0},{"lines":[{"speaker":"Patientin","gender":"f","text":"Guten Tag, muss ich für die Vorsorge zahlen? Kostet das 50 Euro?"},{"speaker":"Sprechstundenhilfe","gender":"f","text":"Die Kontrolle zahlt die Kasse, also nichts für die normale Vorsorge. 50 Euro wäre zu viel."},{"speaker":"Patientin","gender":"f","text":"Und die spezielle Untersuchung? Ist die auch umsonst, oder kostet sie 50 Euro?"},{"speaker":"Sprechstundenhilfe","gender":"f","text":"Nein, die kostet 30 Euro extra, nicht 50 Euro und auch nicht kostenlos. Die Kasse zahlt nur die einfache Kontrolle."},{"speaker":"Patientin","gender":"f","text":"Gut, dann mache ich die spezielle Untersuchung für 30 Euro. Danke."}],"q":"Was kostet die spezielle Untersuchung?","opts":["Nichts.","50 Euro.","30 Euro."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Dr. Klein, einer Hautärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Dr. Klein, warum kommen die Patienten zu Ihnen?"},{"speaker":"Klein","gender":"f","text":"Viele junge Leute kommen wegen Pickeln. Andere haben Probleme mit der Sonne, zum Beispiel nach dem Urlaub. Manche wollen auch nur eine Kontrolle, das ist gut."},{"speaker":"Reporter","gender":"m","text":"Ist Bräune gesund? Viele denken das ja."},{"speaker":"Klein","gender":"f","text":"Nein, das ist ein Irrtum. Bräune ist nicht gesund. Jeder Sonnenbrand schadet der Haut, auch ein kleiner. Das sehe ich jeden Tag in der Praxis."},{"speaker":"Reporter","gender":"m","text":"Wie wichtig ist der Schutz vor der Sonne?"},{"speaker":"Klein","gender":"f","text":"Sehr wichtig, bitte benutzen Sie eine Creme, auch im Frühling. Viele Leute denken, nur im Sommer braucht man Schutz, aber das stimmt nicht. Die Sonne ist auch im April schon stark."},{"speaker":"Reporter","gender":"m","text":"Helfen teure Cremes besser als einfache?"},{"speaker":"Klein","gender":"f","text":"Nicht immer. Eine einfache Creme ist oft genauso gut. Teure Cremes sind nicht immer besser. Wichtig ist der Schutzfaktor, nicht der Preis im Laden."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie für eine gesunde Haut?"},{"speaker":"Klein","gender":"f","text":"Trinken Sie viel Wasser, essen Sie gesund und schlafen Sie genug. Das hilft der Haut sehr. Und gehen Sie einmal im Jahr zur Kontrolle. So bleiben Sie lange gesund."}],"items":[{"q":"Frau Dr. Klein findet, Bräune ist gesund.","correct":"nein"},{"q":"Viele junge Leute kommen wegen Pickeln.","correct":"ja"},{"q":"Sie sagt, jeder Sonnenbrand schadet der Haut.","correct":"ja"},{"q":"Teure Cremes sind immer besser.","correct":"nein"},{"q":"Sie rät, viel Wasser zu trinken und gesund zu essen.","correct":"ja"}]}]};
